VIDEO = {'footer': 'Fuzzing: Finding the Inputs Nobody Tested  ·  Security Basics  ·  Java', 'poster': {'headline': [('FUZZING', 'text'), ('INPUTS NOBODY TESTED', 'accent')], 'taglines': [('Let a program write the inputs nobody thought of', 'gold')], 'before': {'code': 'assertEquals(17980, parse("SHO-1042,2,8990"))', 'note': 'the inputs someone thought of', 'tag': 'BEFORE'}, 'after': {'code': 'Fuzzer.run(harness, seeds)', 'note': 'a hundred thousand inputs nobody did', 'tag': 'AFTER'}}, 'highlight': {'console_green': ['THE EXAMPLE TESTS', 'GUIDED', 'AFTER THE FIX', 'THE FIXED', 'A PROPERTY'], 'console_rose': ['THE RESULT', 'THE CRASHES', 'BLIND', 'BEFORE THE FIX'], 'console_amber': ['HOW THE', 'HOW DELTA', 'THE RULE', 'WHAT A FUZZER', 'WHAT IT COSTS'], 'console_cyan': ['THE INPUT', 'THE MUTATIONS', 'THE FIRST RUNS', 'THE TARGET']}}
